def _seed_task_permissions() -> None:
    """Organization visibility needs a permission everyone holds, and admin oversight its own.

    See ADR-027. `tests/test_permissions.py` checks this data against the catalog.
    """
    bind = op.get_bind()
    bind.execute(
        sa.text("UPDATE permissions SET description = :text WHERE `key` = 'task.view_organization'"),
        {"text": "View tasks shared with the whole organization"},
    )
    bind.execute(
        sa.text("INSERT INTO permissions (`key`, description) VALUES ('task.view_all', :text)"),
        {"text": "View every task in the organization, whatever its visibility"},
    )
    grants = {
        'task.view_all': ('owner', 'admin'),
        'task.view_organization': ('department_manager', 'team_lead', 'member'),
    }
    for permission, roles in grants.items():
        for role in roles:
            bind.execute(
                sa.text(
                    "INSERT INTO role_permissions (role_id, permission_id) "
                    "SELECT r.id, p.id FROM roles r, permissions p "
                    "WHERE r.`key` = :role AND p.`key` = :permission"
                ),
                {"role": role, "permission": permission},
            )
    # ### end Alembic commands ###


